                                ),
                                style = Stroke(width = 4f)
                            )
                        }
                    }
                }
                Spacer(modifier = Modifier.height(16.dp))

                // --- Total Formateado ---
                Text(
                    "Total: $${"%.2f".format(uiState.totalAmount)}",
