        }
    }
}

package dev.dgset.cajasva.features.results.viewmodel

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import android.net.Uri
import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dev.dgset.cajasva.domain.model.DetectedObject
import dev.dgset.cajasva.domain.repository.CashRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.IOException
import javax.inject.Inject
import androidx.exifinterface.media.ExifInterface

@HiltViewModel
class ResultsViewModel @Inject constructor(
    private val cashRepository: CashRepository,
    @ApplicationContext private val context: Context
) : ViewModel() {

    private val _uiState = MutableStateFlow(ResultsUiState())
    val uiState = _uiState.asStateFlow()

    fun processImageUri(imageUri: Uri) {
        Log.d("ResultsViewModel", "Processing image URI: $imageUri")
        _uiState.update { it.copy(isLoading = true) }

        viewModelScope.launch {
            try {
                // Convertir URI a Bitmap en hilo de background
                val bitmap = withContext(Dispatchers.IO) {
                    loadBitmapFromUri(imageUri)
                }

                Log.d("ResultsViewModel", "Bitmap loaded: ${bitmap.width}x${bitmap.height}")

                // ¡NUEVO! Guardar las dimensiones originales
                val originalWidth = bitmap.width
                val originalHeight = bitmap.height
                val aspectRatio = if (originalHeight > 0) originalWidth.toFloat() / originalHeight.toFloat() else 1f
                _uiState.update { it.copy(
                    originalImageWidth = originalWidth,
                    originalImageHeight = originalHeight,
                    imageAspectRatio = aspectRatio
                )}

                // Procesar con el pipeline de ML
                cashRepository.detectAndClassify(bitmap).fold(
                    onSuccess = { detectedObjects ->
                        Log.d("ResultsViewModel", "Detection successful: ${detectedObjects.size} objects detected")
                        detectedObjects.forEach { obj ->
                            Log.d("ResultsViewModel", "Detected: ${obj.label} - $${obj.value}")
                        }

                        val totalAmount = detectedObjects.sumOf { it.value }
                        Log.d("ResultsViewModel", "Total amount: $$totalAmount")

                        _uiState.update {
                            it.copy(
                                isLoading = false,
                                breakdown = detectedObjects,
                                totalAmount = totalAmount
                            )
                        }
                    },
                    onFailure = { error ->
                        Log.e("ResultsViewModel", "Detection failed: ${error.message}", error)
                        _uiState.update {
                            it.copy(
                                isLoading = false,
                                error = error.message ?: "Error desconocido"
                            )
                        }
                    }
                )
            } catch (e: Exception) {
                Log.e("ResultsViewModel", "Error processing image: ${e.message}", e)
                _uiState.update {
                    it.copy(
                        isLoading = false,
                        error = "Error al procesar imagen: ${e.message}"
                    )
                }
            }
        }
    }

    private fun loadBitmapFromUri(uri: Uri): Bitmap {
        return try {
            Log.d("ResultsViewModel", "Loading bitmap from URI: $uri")

            // Abrir input stream desde la URI
            val inputStream = context.contentResolver.openInputStream(uri)
                ?: throw IOException("No se pudo abrir el archivo de imagen")

            // Primero, obtener las dimensiones de la imagen sin decodificarla completamente
            val options = BitmapFactory.Options().apply {
                inJustDecodeBounds = true
            }

            BitmapFactory.decodeStream(inputStream, null, options)
            inputStream.close()

            // Calcular el factor de escala para reducir el tamaño si es necesario
            val targetSize = 1024 // Tamaño máximo para optimizar rendimiento
            val scaleFactor = calculateInSampleSize(options, targetSize, targetSize)

            // Decodificar la imagen con el factor de escala
            val finalOptions = BitmapFactory.Options().apply {
                inSampleSize = scaleFactor
                inPreferredConfig = Bitmap.Config.ARGB_8888
            }

            val inputStream2 = context.contentResolver.openInputStream(uri)
                ?: throw IOException("No se pudo abrir el archivo de imagen")

            val bitmap = BitmapFactory.decodeStream(inputStream2, null, finalOptions)
                ?: throw IOException("No se pudo decodificar la imagen")

            inputStream2.close()

            // Corregir rotación basada en EXIF
            val correctedBitmap = correctImageRotation(bitmap, uri)

            Log.d("ResultsViewModel", "Bitmap loaded successfully: ${correctedBitmap.width}x${correctedBitmap.height}")
            correctedBitmap

        } catch (e: Exception) {
            Log.e("ResultsViewModel", "Error loading bitmap from URI: ${e.message}", e)
            // Crear bitmap de prueba como fallback
            Bitmap.createBitmap(640, 640, Bitmap.Config.ARGB_8888)
        }
    }

    private fun calculateInSampleSize(options: BitmapFactory.Options, reqWidth: Int, reqHeight: Int): Int {
        val height = options.outHeight
        val width = options.outWidth
        var inSampleSize = 1

        if (height > reqHeight || width > reqWidth) {
            val halfHeight = height / 2
            val halfWidth = width / 2

            while ((halfHeight / inSampleSize) >= reqHeight && (halfWidth / inSampleSize) >= reqWidth) {
                inSampleSize *= 2
            }
        }

        return inSampleSize
    }

    private fun correctImageRotation(bitmap: Bitmap, uri: Uri): Bitmap {
        return try {
            val inputStream = context.contentResolver.openInputStream(uri)
            val exif = ExifInterface(inputStream!!)
            val orientation = exif.getAttributeInt(
                ExifInterface.TAG_ORIENTATION,
                ExifInterface.ORIENTATION_NORMAL
            )
            inputStream.close()

            val rotationDegrees = when (orientation) {
                ExifInterface.ORIENTATION_ROTATE_90 -> 90f
                ExifInterface.ORIENTATION_ROTATE_180 -> 180f
                ExifInterface.ORIENTATION_ROTATE_270 -> 270f
                else -> 0f
            }

            if (rotationDegrees != 0f) {
                val matrix = Matrix().apply {
                    postRotate(rotationDegrees)
                }
                Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
            } else {
                bitmap
            }
        } catch (e: Exception) {
            Log.w("ResultsViewModel", "Could not read EXIF info, using original bitmap", e)
            bitmap
        }
    }

    private fun processDetectionsAndUpdateState(detections: List<DetectedObject>) {
        if (detections.isEmpty()) {
            _uiState.update { it.copy(isLoading = false, breakdown = emptyList(), totalAmount = 0.0) }
            return
        }

        val ref10Pesos = detections.find { it.label == "moneda_10" }
        val refPixelWidth = ref10Pesos?.boundingBox?.width()
        val refRealWidthMm = 28.0

        var total = 0.0
        val processedDetections = detections.map { detection ->
            var detectedValue = 0.0

            when (detection.label) {
                "billete_20" -> detectedValue = 20.0
                "billete_50" -> detectedValue = 50.0
                "billete_100" -> detectedValue = 100.0
                "billete_200" -> detectedValue = 200.0
                "billete_500" -> detectedValue = 500.0
                "billete_1000" -> detectedValue = 1000.0
                "moneda_0_50" -> detectedValue = 0.5
                "moneda_10" -> detectedValue = 10.0
                "moneda_2_anverso" -> detectedValue = 2.0
                "moneda_5_anverso" -> detectedValue = 5.0
                "moneda_1_anverso", "moneda_reverso_comun" -> {
                    if (refPixelWidth != null && refPixelWidth > 0) {
                        val ratio = detection.boundingBox.width() / refPixelWidth
                        detectedValue = when {
                            ratio < 0.78 -> 1.0
                            ratio < 0.86 -> 2.0
                            else -> 5.0
                        }
                    } else {
                        val pixelWidth = detection.boundingBox.width()
                        detectedValue = when {
                            pixelWidth < 150 -> 1.0
                            pixelWidth < 180 -> 2.0
                            else -> 5.0
                        }
                    }
                }
            }
            total += detectedValue
            detection.copy(value = detectedValue)
        }

        _uiState.update { it.copy(isLoading = false, totalAmount = total, breakdown = processedDetections) }
    }

    fun onScanAgainClick() {
        // TODO: Navegación a escaneo
    }

    fun onBackClick() {
        // TODO: Navegación hacia atrás
    }
}

package dev.dgset.cajasva.features.results.viewmodel

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import android.net.Uri
import android.util.Log
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dev.dgset.cajasva.domain.model.DetectedObject
import dev.dgset.cajasva.domain.repository.CashRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.io.IOException
import javax.inject.Inject
import androidx.exifinterface.media.ExifInterface

@HiltViewModel
class ResultsViewModel @Inject constructor(
    private val cashRepository: CashRepository,
    @ApplicationContext private val context: Context
) : ViewModel() {

    private val _uiState = MutableStateFlow(ResultsUiState())
    val uiState = _uiState.asStateFlow()

    fun processImageUri(imageUri: Uri) {
        Log.d("ResultsViewModel", "Processing image URI: $imageUri")
        _uiState.update { it.copy(isLoading = true) }

        viewModelScope.launch {
            try {
                // Convertir URI a Bitmap en hilo de background
                val bitmap = withContext(Dispatchers.IO) {
                    loadBitmapFromUri(imageUri)
                }

                Log.d("ResultsViewModel", "Bitmap loaded: ${bitmap.width}x${bitmap.height}")

                // ¡NUEVO! Guardar las dimensiones originales
                val originalWidth = bitmap.width
                val originalHeight = bitmap.height
                val aspectRatio = if (originalHeight > 0) originalWidth.toFloat() / originalHeight.toFloat() else 1f
                _uiState.update { it.copy(
                    originalImageWidth = originalWidth,
                    originalImageHeight = originalHeight,
                    imageAspectRatio = aspectRatio
                )}

                // Procesar con el pipeline de ML
                cashRepository.detectAndClassify(bitmap).fold(
                    onSuccess = { detectedObjects ->
                        Log.d("ResultsViewModel", "Detection successful: ${detectedObjects.size} objects detected")
                        detectedObjects.forEach { obj ->
                            Log.d("ResultsViewModel", "Detected: ${obj.label} - $${obj.value}")
                        }

                        val totalAmount = detectedObjects.sumOf { it.value }
                        Log.d("ResultsViewModel", "Total amount: $$totalAmount")

                        _uiState.update {
                            it.copy(
                                isLoading = false,
                                breakdown = detectedObjects,
                                totalAmount = totalAmount
                            )
                        }
                    },
                    onFailure = { error ->
                        Log.e("ResultsViewModel", "Detection failed: ${error.message}", error)
                        _uiState.update {
                            it.copy(
                                isLoading = false,
                                error = error.message ?: "Error desconocido"
                            )
                        }
                    }
                )
            } catch (e: Exception) {
                Log.e("ResultsViewModel", "Error processing image: ${e.message}", e)
                _uiState.update {
                    it.copy(
                        isLoading = false,
                        error = "Error al procesar imagen: ${e.message}"
                    )
                }
            }
        }
    }

    private fun loadBitmapFromUri(uri: Uri): Bitmap {
        return try {
            Log.d("ResultsViewModel", "Loading bitmap from URI: $uri")

            val inputStream = context.contentResolver.openInputStream(uri)
                ?: throw IOException("No se pudo abrir el archivo de imagen")

            val options = BitmapFactory.Options().apply {
                inJustDecodeBounds = true
            }

            BitmapFactory.decodeStream(inputStream, null, options)
            inputStream.close()

            val targetSize = 1024
            val scaleFactor = calculateInSampleSize(options, targetSize)

            val finalOptions = BitmapFactory.Options().apply {
                inSampleSize = scaleFactor
                inPreferredConfig = Bitmap.Config.ARGB_8888
            }

            val inputStream2 = context.contentResolver.openInputStream(uri)
                ?: throw IOException("No se pudo abrir el archivo de imagen")

            val bitmap = BitmapFactory.decodeStream(inputStream2, null, finalOptions)
                ?: throw IOException("No se pudo decodificar la imagen")

            inputStream2.close()

            correctImageRotation(bitmap, uri)
        } catch (e: Exception) {
            Log.e("ResultsViewModel", "Error loading bitmap from URI: ${e.message}", e)
            Bitmap.createBitmap(640, 640, Bitmap.Config.ARGB_8888)
        }
    }

    private fun calculateInSampleSize(options: BitmapFactory.Options, reqSize: Int): Int {
        val height = options.outHeight
        val width = options.outWidth
        var inSampleSize = 1

        if (height > reqSize || width > reqSize) {
            val halfHeight = height / 2
            val halfWidth = width / 2

            while ((halfHeight / inSampleSize) >= reqSize && (halfWidth / inSampleSize) >= reqSize) {
                inSampleSize *= 2
            }
        }

        return inSampleSize
    }

    private fun correctImageRotation(bitmap: Bitmap, uri: Uri): Bitmap {
        return try {
            val inputStream = context.contentResolver.openInputStream(uri)
            val exif = ExifInterface(inputStream!!)
            val orientation = exif.getAttributeInt(
                ExifInterface.TAG_ORIENTATION,
                ExifInterface.ORIENTATION_NORMAL
            )
            inputStream.close()

            val rotationDegrees = when (orientation) {
                ExifInterface.ORIENTATION_ROTATE_90 -> 90f
                ExifInterface.ORIENTATION_ROTATE_180 -> 180f
                ExifInterface.ORIENTATION_ROTATE_270 -> 270f
                else -> 0f
            }

            if (rotationDegrees != 0f) {
                val matrix = Matrix().apply {
                    postRotate(rotationDegrees)
                }
                Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
            } else {
                bitmap
            }
        } catch (e: Exception) {
            Log.w("ResultsViewModel", "Could not read EXIF info, using original bitmap", e)
            bitmap
        }
    }

    private fun processDetectionsAndUpdateState(detections: List<DetectedObject>) {
        if (detections.isEmpty()) {
            _uiState.update { it.copy(isLoading = false, breakdown = emptyList(), totalAmount = 0.0) }
            return
        }

        var total = 0.0
        val processedDetections = detections.map { detection ->
            var detectedValue = 0.0

            when (detection.label) {
                "billete_20" -> detectedValue = 20.0
                "billete_50" -> detectedValue = 50.0
                "billete_100" -> detectedValue = 100.0
                "billete_200" -> detectedValue = 200.0
                "billete_500" -> detectedValue = 500.0
                "billete_1000" -> detectedValue = 1000.0
                "moneda_0_50" -> detectedValue = 0.5
                "moneda_10" -> detectedValue = 10.0
                "moneda_2_anverso" -> detectedValue = 2.0
                "moneda_5_anverso" -> detectedValue = 5.0
                "moneda_1_anverso", "moneda_reverso_comun" -> {
                    detectedValue = when {
                        detection.boundingBox.width() < 150 -> 1.0
                        detection.boundingBox.width() < 180 -> 2.0
                        else -> 5.0
                    }
                }
            }
            total += detectedValue
            detection.copy(value = detectedValue)
        }

        _uiState.update { it.copy(isLoading = false, totalAmount = total, breakdown = processedDetections) }
    }
}
